struct MockAliasPort{
 using Actor=RE::Actor;inline static std::array<Actor*,5>assigned{},pending{},detaching{};inline static std::array<bool,5>parked{};inline static std::uint64_t frame{};inline static unsigned forces{},clears{};inline static bool delayFill{},blockClear{},failForce{},rejectClear{},delayDetach{};inline static std::array<AliasDetachState,5>detachOverride{};
 struct Request{unsigned slot,token,actor;};inline static std::vector<Request>requests;
 static bool Ready(){return true;}static unsigned Identity(Actor*a){return a?a->GetFormID():0;}static unsigned Marker(unsigned i){return 0x100000+i;}static unsigned Read(unsigned i){return assigned[i]?Identity(assigned[i]):parked[i]?Marker(i):0;}static auto Frame(){return frame;}
 static bool Parked(unsigned i,unsigned ref){return ref==Marker(i);}static bool Available(unsigned i,unsigned ref){return !ref||Parked(i,ref);}static AliasDetachState Detached(unsigned i,unsigned){return detachOverride[i]!=AliasDetachState::Detached?detachOverride[i]:detaching[i]?AliasDetachState::Attached:AliasDetachState::Detached;}
 static void Force(unsigned i,Actor*a,unsigned,unsigned){++forces;if(failForce)return;parked[i]=false;if(delayFill)pending[i]=a;else{assigned[i]=a;a->hasPerformance=true;}}
 static bool Evict(unsigned i,unsigned token,unsigned actor,unsigned){++clears;if(rejectClear)return false;requests.push_back({i,token,actor});return true;}
 static void Reset(){assigned={};pending={};detaching={};parked={};detachOverride={};requests.clear();delayFill=blockClear=failForce=rejectClear=delayDetach=false;}
};
class PerformanceAlias{
public:
 inline static AliasLeaseTable<MockAliasPort>table;
 static AliasResult Acquire(RE::Actor*a,std::uint64_t&t,unsigned slot){return table.Acquire(a,t,slot);}
 static bool Owned(std::uint64_t t,RE::Actor*a){return a&&table.Owned(t,a->GetFormID());}
 static AliasResult Release(std::uint64_t t,RE::Actor*a){return a?table.Release(t,a->GetFormID()):AliasResult::Failed;}
 static AliasResult ReleaseLost(std::uint64_t t){auto actor=table.ActorOf(t);return actor?table.Release(t,actor):AliasResult::Ready;}
 static void Maintain(std::uint64_t,RE::Actor*){}static void UserRetry(){}
 static void ResetWorld(){table.Reset();MockAliasPort::Reset();}
 static void Tick(){++MockAliasPort::frame;if(!MockAliasPort::delayFill)for(unsigned i=0;i<5;i++)if(MockAliasPort::pending[i]){MockAliasPort::assigned[i]=MockAliasPort::pending[i];MockAliasPort::pending[i]=nullptr;MockAliasPort::assigned[i]->hasPerformance=true;}
  if(MockAliasPort::blockClear)return;auto requests=std::move(MockAliasPort::requests);MockAliasPort::requests.clear();for(auto&r:requests){
   if(MockAliasPort::Read(r.slot)==r.actor||MockAliasPort::Available(r.slot,MockAliasPort::Read(r.slot))){MockAliasPort::detaching[r.slot]=MockAliasPort::assigned[r.slot];MockAliasPort::assigned[r.slot]=nullptr;MockAliasPort::pending[r.slot]=nullptr;MockAliasPort::parked[r.slot]=true;}
  }
  if(!MockAliasPort::delayDetach)for(auto*&a:MockAliasPort::detaching)if(a){a->hasPerformance=false;++a->endCalls;a=nullptr;}

 }
};
